    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # colored bar indicates the axis-aligned boundary rails; isolated marker draws orthogonal ray to matching rail.
    base=next((v for row in grid for v in row if v not in (1,)),None)
    # find color of repeated bar and singleton marker
    from collections import Counter
    cnt=Counter(v for row in grid for v in row if v!=1)
    rail=max(cnt,key=lambda v:cnt[v])
    mark=next(v for v in cnt if v!=rail)
    # horizontal rail at top/bottom implies marker draws vertical towards opposite edge; likewise vertical.
    bar=[]
    for r in range(h):
        cols=[c for c in range(w) if grid[r][c]==rail]
        if len(cols)>1: bar.append(('row',r,min(cols),max(cols)))
    for c in range(w):
        rows=[r for r in range(h) if grid[r][c]==rail]
        if len(rows)>1: bar.append(('col',c,min(rows),max(rows)))
    mr,mc=next((r,c) for r in range(h) for c in range(w) if grid[r][c]==mark)
    if any(axis=='row' for axis,*_ in bar):
        # project marker column through full height, recolor marker to 4
        out[mr][mc]=4
        for r in range(h):
            if r!=mr: out[r][mc]=mark
    else:
        out[mr][mc]=4
        for c in range(w):
            if c!=mc: out[mr][c]=mark
    return out

